const { Client } = require("@hubspot/api-client");
const hubspotClient = new Client({ accessToken: $vars.hs_wetravel_app_key });
const status = { Paid: 180, Deposit: 176, Cancelled: 178, Pending: 242 };
const contact_properties = $('get_contact_data').all()[0].json.properties
const company_properties = $('find_company').all()[0].json.properties

const objectType = "company";
const objectId = company_properties.hs_object_id;
const toObjectType = "contact";
const toObjectId = contact_properties.hs_object_id;
const AssociationSpec = [
  {
    // Primary company association
    associationTypeId: 2,
    associationCategory: "HUBSPOT_DEFINED",
  },
];

const apiResponse = await hubspotClient.crm.associations.v4.basicApi.create(
  objectType,
  objectId,
  toObjectType,
  toObjectId,
  AssociationSpec
);
return apiResponse;

